read_annot <- function(path){x<-readLines(gzfile(path),warn=FALSE,encoding="UTF-8");s<-match("!platform_table_begin",x)+1L;e<-match("!platform_table_end",x)-1L;read.delim(text=paste(x[s:e],collapse="\n"),sep="\t",quote="",stringsAsFactors=FALSE,check.names=FALSE)}
a<-read_annot('E:/RProject/_np_stage/geo_data/GPL13158.annot.gz'); m<-setNames(toupper(trimws(a[['Gene symbol']])),a[['ID']]); cat(class(a),class(m),length(m),'\n'); print(head(m)); core<-read.csv('E:/RProject/_np_stage/geo_data/C_main.csv',fileEncoding='UTF-8',stringsAsFactors=FALSE)$gene; cat('coreclass',class(core),length(core),'\n')
